import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) n];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());
        long[] c = new long[(int) n];
        for (int i = 0; i < c.length; i++) c[i] = Long.parseLong(next());
        long[] d = new long[(int) n];
        for (int i = 0; i < d.length; i++) d[i] = Long.parseLong(next());

        Map<Long, Long> sums = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) sums.merge(a[i] + b[j], 1L, Long::sum);
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) total += sums.getOrDefault(-(c[i] + d[j]), 0L);
        }
        System.out.println(total);
    }
}
